    "monitoring": {
      "adapter": "noop",
      "enabled": true,
      "connectionConfig": {},
      "thresholds": {
        "errorRatePercent": 5.0,
        "latencyP99Ms": 2000,
        "alertCountWindow": "1h",
        "alertCountThreshold": 10
      }
    }
  },
  "identity": {
    "providers": [
      {
        "type": "local",
        "enabled": true,
        "warningBanner": true,
        "allowedInProduction": false
      }
